    }

    public boolean isCondition() {
        return (type & CONDITION) != 0;
    }

    public boolean isStopBacktrack() {
        return (type & STOP_BACKTRACK) != 0;
    }

    public boolean isAbsent() {
        return (type & ABSENT) != 0;
    }
