  CMP_OP_AST_NODE_MAP = {
    '<': _ast.Lt,
    '<=': _ast.LtE,
    '==': _ast.Eq,
    '!=': _ast.NotEq,
    '>': _ast.Gt,
    '>=': _ast.GtE,
