public class CommandList extends BaseCommand {

	public CommandList() {
		aliases.add("list");
		aliases.add("ls");

		hasGateParam = false;

		helpDescription = "Display a list of the gates";
	}

	public void perform() {
		List<String> ids = new ArrayList<String>();

		for (Gate gate : Gate.getAll()) {
			ids.add(Conf.colorAlly + gate.getId());
		}

		if (ids.size() == 0) {
			sendMessage("There are no gates yet.");
			return;
		}

		sendMessage("There are currently "+ids.size()+" gates on this server: ");
		sendMessage(TextUtil.implode(ids, Conf.colorSystem+", "));
	}

}
src/org/mcteam/ancientgates/listeners/PluginBlockListener.java
public class PluginBlockListener extends BlockListener {
	@Override
	public void onBlockPhysics(BlockPhysicsEvent event) {
		if (event.isCancelled()) {
			return;
		}

		if (event.getBlock().getType() != Material.PORTAL) {
			return;
		}

		if (isBlockInPortal(event.getBlock())) {
			event.setCancelled(true);
		}
	}

	public boolean isBlockInPortal(Block block) {
		if (block.getFace(BlockFace.UP).getType() == Material.AIR) {
			return false;
		}

		if (block.getFace(BlockFace.DOWN).getType() == Material.AIR) {
			return false;
		}

		if ( block.getFace(BlockFace.NORTH).getType() != Material.AIR && block.getFace(BlockFace.SOUTH).getType() != Material.AIR ) {
			return true;
		}

		if ( block.getFace(BlockFace.WEST).getType() != Material.AIR && block.getFace(BlockFace.EAST).getType() != Material.AIR ) {
			return true;
		}

		return false;
	}
}
